const fs = require('fs');
const failures = [];

function readNum(name) {
  if (!fs.existsSync(name)) {
    failures.push(`${name}: file missing`);
    return null;
  }
  const raw = fs.readFileSync(name, 'utf8').trim();
  if (raw === '') {
    failures.push(`${name}: empty file`);
    return null;
  }
  const n = Number(raw);
  if (!Number.isFinite(n)) {
    failures.push(`${name}: not a finite number (${JSON.stringify(raw)})`);
    return null;
  }
  return n;
}

function assertEq(label, actual, expected) {
  const ok = actual !== null && actual === expected;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${label}: actual=${actual} expected=${expected}`);
  if (!ok) failures.push(`${label} mismatch: actual=${actual} expected=${expected}`);
}

const seed = readNum('seed.txt');
const stage1 = readNum('stage1.txt');
const stage2 = readNum('stage2.txt');
const stage3 = readNum('stage3.txt');

assertEq('stage1 == seed + 2', stage1, seed === null ? null : seed + 2);
assertEq('stage2 == stage1 * stage1', stage2, stage1 === null ? null : stage1 * stage1);
assertEq('stage3 == stage2 - 4', stage3, stage2 === null ? null : stage2 - 4);

console.log('values: seed=%s stage1=%s stage2=%s stage3=%s', seed, stage1, stage2, stage3);

if (failures.length > 0) {
  console.error(`VERIFICATION FAILED (${failures.length} problem(s)):`);
  for (const f of failures) console.error(` - ${f}`);
  process.exit(1);
}
console.log('VERIFICATION OK: all saved stages are consistent');
