const fs = require('fs');
const path = require('path');
const stages = ['stage1', 'stage2', 'stage3'];
const errors = [];
const values = {};

// Read each saved stage file; never compute a value here, only read.
for (const name of stages) {
  const file = path.join(process.cwd(), name + '.txt');
  if (!fs.existsSync(file)) { errors.push(`${name}.txt is missing`); continue; }
  const raw = fs.readFileSync(file, 'utf8').trim();
  if (raw === '') { errors.push(`${name}.txt is empty`); continue; }
  const n = Number(raw);
  if (!Number.isFinite(n)) { errors.push(`${name}.txt is not a finite number: ${JSON.stringify(raw)}`); continue; }
  values[name] = n;
  console.log(`read ${name}.txt = ${n}`);
}
if (errors.length) { console.error('FAILED: ' + errors.join('; ')); process.exit(1); }

// Ordered object so the keys land as stage1, stage2, stage3.
const answer = { stage1: values.stage1, stage2: values.stage2, stage3: values.stage3 };
fs.writeFileSync('answer.json', JSON.stringify(answer, null, 2) + '\n', 'utf8');
console.log('wrote answer.json:', JSON.stringify(answer));

// Validate: re-read from disk and compare against the saved stage files.
const text = fs.readFileSync('answer.json', 'utf8');
let parsed;
try { parsed = JSON.parse(text); } catch (e) { console.error('FAILED: answer.json is not valid JSON: ' + e.message); process.exit(1); }

const keys = Object.keys(parsed);
if (keys.join(',') !== 'stage1,stage2,stage3') errors.push(`keys are ${JSON.stringify(keys)}, expected ["stage1","stage2","stage3"]`);
for (const name of stages) {
  if (typeof parsed[name] !== 'number') { errors.push(`${name} is not a numeric value in JSON (got ${typeof parsed[name]})`); continue; }
  const onDisk = Number(fs.readFileSync(name + '.txt', 'utf8').trim());
  if (parsed[name] === onDisk) console.log(`PASS answer.json.${name} === ${name}.txt: ${parsed[name]}`);
  else errors.push(`${name} mismatch: json=${parsed[name]} file=${onDisk}`);
}

if (errors.length) { console.error('VALIDATION FAILED: ' + errors.join('; ')); process.exit(1); }
console.log('VALIDATION OK: answer.json matches the saved stage values');
EOF
